\label{an:dilution}
Let $0<p\le1$, let $1/2\le d\nu/d\sigma\le3/2$, and put
\[
 c=c(p)=\frac{3-\sqrt{9-8p}}2,\qquad p=\frac{c(3-c)}2.
\]
For every probability $\mu$, allowing infinite energy,
\begin{equation}
 E(p\mu+(1-p)\nu)\ge pcE(\mu)-\frac92c(1-p).
 \label{an:dilution-bound}
\end{equation}

\label{an:entropy-projection}
The function $J_u$ has a unique minimizer $Y_u\in\mathfrak a$.
The probability
\begin{equation}
 d\eta_u=Z_u(Y_u)^{-1}e^{-\gamma u-W+h_{Y_u}}d\sigma
 \label{an:exponential-family}
\end{equation}
is an exact second design of finite entropy and energy. It uniquely
minimizes $H(\nu)+\int(\gamma u+W)d\nu$ among finite-entropy measures
on that fibre, and
\begin{equation}
 \Ent(\nu\mid\eta_u)
 =H(\nu)+\int(\gamma u+W)d\nu+\log Z_u(Y_u)
 \label{an:pythagoras}
\end{equation}
for every finite-entropy second design $\nu$.

\label{an:equilibrium}
For $0\le\gamma<12/7$ and $W\in C^\infty(X,\R)$,
$\mathcal F_{\gamma,W}$ attains its minimum. Every minimizer is smooth
and strictly positive. Its Monge--Amp\`ere potential, normalized by
$\sup_Xu=0$, and unique traceless multiplier satisfy
\begin{equation}
 \operatorname{MA}(u)=
 \frac{e^{-\gamma u-W+h_Y}}
 {\int e^{-\gamma u-W+h_Y}d\sigma}\,\sigma.
 \label{an:equilibrium-pde}
\end{equation}
For $\gamma$ in a compact subinterval of $[0,12/7)$ and $W$ in a bounded
subset of $C^\infty$, the potentials, densities, and multipliers have
uniform bounds in every smooth norm, and the densities have a common
positive lower bound. The minimizer itself is not asserted to be unique.

\label{an:lower-comparison}
For each fixed finite collection in \eqref{an:continuous-envelopes}
there is a finite constant $C_r$ such that, on every configuration,
\begin{equation}
 E_k\ge E_r(L_k)-\frac{2\log k+C_r}{k},
 \qquad E_k\ge-\frac{\log N_k}{k}.
 \label{an:LC}
\end{equation}
The inequalities include determinant-zero configurations, where
$E_k=+\infty$.

\label{geo:cusp}
Suppose a balanced \(m\)-ray frame is partitioned into \(d\) nonempty
groups, with actual maximum within-group projector distance
\(\delta\le1/(2d)\). Suppose
\[
 a(I-P_i)\preceq C_i\preceq b(I-P_i),\qquad 0<a\le b.
\]
For a constant \(\kappa_d>0\) depending only on dimension,
\begin{equation}
 F_d(C)\le9\eta_db\delta^2-\frac{\kappa_da}{m}\delta.
 \label{geo:negative-cusp}
\end{equation}
One may take \(\kappa_3=325/536313\).

\label{lem:coherent-graph-integral}
Let $G$ be a fixed connected Eulerian directed multigraph on $r$
vertices, with multiplicities $n_{ab}$.  Then
\begin{equation}
 I_m(G):=\int\prod_{a,b}\langle z_a,z_b\rangle^{m n_{ab}}
                   \,d\sigma(z_1)\cdots d\sigma(z_r)
 =D_m^{-(r-1)}\tau(G)^{-q}(1+o(1)).
 \label{eq:coherent-graph-integral}
\end{equation}
Furthermore $|I_m(G)|\leq C_GD_m^{-(r-1)}$ for all sufficiently
large $m$.

\label{lem:tree-one-noncrossing}
For a cycle quotient, $\tau(G_\pi)=1$ if and only if $\pi$ is
noncrossing in the cyclic order.

\label{thm:coherent-free-limit}
For every finite positive integer $q$ and $\rho>0$, the support of
$\nu_{q,\rho}$ is unbounded.  Nevertheless its moment-generating
function is entire, and for $t\geq0$,
\begin{equation}
 \int e^{tx}\,d\nu_{q,\rho}(x)
 \leq1+\frac{\exp\{\rho(e^t-1)\}-1}{\rho}.
 \label{eq:coherent-entire-bound}
\end{equation}
In particular, for $R\geq\rho$,
\begin{equation}
 \nu_{q,\rho}([R,\infty))
 \leq\max(1,\rho^{-1})
       \exp\{-R\log(R/\rho)+R-\rho\}.
 \label{eq:coherent-poisson-tail}
\end{equation}
As $q\to\infty$ through integers, $\nu_{q,\rho}$ converges weakly
and in every fixed positive moment to the mean-one
Marchenko--Pastur law of aspect ratio $\rho$.

\label{op:heap}
For every nonempty heap,
\begin{equation}
 [H](-\log M)=\Omega_H'(0),\qquad
 [H]\log Z=(-1)^{|H|+1}\Omega_H'(0).
 \label{op:heap-coefficient}
\end{equation}
Disconnected heaps have zero coefficient. For a natural labeling of a heap
with $n$ elements, the first coefficient also equals
\begin{equation}
 \Omega_H'(0)=\sum_{\pi\in\mathcal L(H)}
 \frac{(-1)^{\operatorname{des}(\pi)}}
 {n\binom{n-1}{\operatorname{des}(\pi)}},
 \label{op:eulerian}
\end{equation}
where $\mathcal L(H)$ denotes its linear extensions.

\label{op:hyperbolic-clock}
For $\tau\ge0$,
\begin{equation}
 T_\tau=\left(\frac{\ad_G}{\sinh\ad_G}\right)^\tau
 =\mathbb E e^{-S_\tau L},\qquad
 S_\tau=\sum_{j\ge1}Y_j,\quad
 Y_j\sim\operatorname{Gamma}\left(\tau,\text{rate }\pi^2j^2\right)
 \label{op:gamma-clock}
\end{equation}
with independent summands. It is a random-unitary semigroup. Put
$S_{\tau,R}=\sum_{j\le R}Y_j$ and
$a_R=\mathbb E(S_\tau-S_{\tau,R})$. The finite and mean-corrected channels
obey
\begin{align}
 \|\mathbb Ee^{-S_{\tau,R}L}A-T_\tau A\|
 &\le\frac{\tau}{\pi^2R}\|\ad_G^2A\|,\label{op:clock-first}\\
 \|\mathbb Ee^{-(S_{\tau,R}+a_R)L}A-T_\tau A\|
 &\le\frac{\tau}{6\pi^4R^3}\|\ad_G^4A\|.
 \label{op:clock-mean}
\end{align}

\label{op:metric-range}
The function \eqref{op:bessel-mean} defines a symmetric normalized
operator-monotone mean exactly for $\nu\ge-1/2$. In that range,
\begin{equation}
 \mathcal J_{m_\nu,\rho}^{-1}(\dot\rho)
 =\phi_\nu(\ad_K/2)A.
 \label{op:bessel-score}
\end{equation}
The endpoint is the symmetric logarithmic derivative (SLD) metric;
$\nu=1/2$ is the Bogoliubov--Kubo--Mori (BKM) metric; the limit as
$\nu\to\infty$ is the geometric-mean metric.

\label{q:thm-wire-gap}
Under \eqref{q:cp-sandwich}, set
\begin{equation}
 \mathcal B(x,y)=\frac{2xy(1+xy)}{(1-x)^2(1-y)^2}.
 \label{q:Bxy}
\end{equation}
Let $C$ be the symmetric matrix indexed by edges, with zero diagonal,
with $C_{ef}=0$ for disjoint edges, and with
$C_{ef}=\mathcal B(\delta_{v,e},\delta_{v,f})$ when $e,f$ meet at $v$.
If its spectral radius satisfies $\rho(C)<1$, then
\begin{equation}
 H_{\mathrm{block}}\geq
 [1-\rho(C)](I-G_{\mathrm{all}}),
 \label{q:block-gap}
\end{equation}
where $G_{\mathrm{all}}$ projects onto its full ground space.
The same statement holds uniformly for a family of finite graphs if
their matrices $C$ have a common spectral-radius upper bound below one.

\label{q:lem-seed}
Let $H_{\mathrm{micro}}=\sum_a h_a$ be a frustration-free microscopic
Hamiltonian with $h_a\geq0$.  For every coarse edge $e$, let $P_e$ be
its two-block patch and let $H_{P_e}$ be the sum of microscopic terms
contained in it.  Assume
\[
 \ker H_{P_e}=\mathcal R_e,\qquad
 H_{P_e}\geq g_* (I-G_e),\qquad g_*>0.
\]
Suppose every microscopic term lies in at least one and at most $m$
patches.  Then the two Hamiltonians have the same full kernel and
\begin{equation}
 \operatorname{gap}H_{\mathrm{micro}}
 \geq \frac{g_*}{m}\operatorname{gap}H_{\mathrm{block}}.
 \label{q:seed-comparison}
\end{equation}

\label{q:cor-aklt}
Let $\mathcal G$ be a simple graph of maximum degree $\Delta\geq2$.
Replace every edge by a chain with $n=2\ell$ additional spin-one
vertices, and give each original degree-$d$ vertex spin $d/2$.
For connected finite regions made of whole half-wire blocks, with at
least two blocks, suppose
\[
 2(\Delta-1)\mathcal B(\delta_\ell,\delta_\ell)<1.
\]
Then the standard microscopic AKLT Hamiltonians have the uniform bound
\begin{equation}
 \operatorname{gap}H_{\mathrm{AKLT}}
 \geq\frac{g_*(\Delta,\ell)}\Delta
       \left[1-2(\Delta-1)
                    \mathcal B(\delta_\ell,\delta_\ell)\right]>0,
 \label{q:aklt-gap}
\end{equation}
where $g_*(\Delta,\ell)>0$ is the minimum positive gap of the finitely
many two-block patch Hamiltonians with these parameters.  In particular,
\begin{equation}
 \ell=\left\lceil\log_9(144\Delta)\right\rceil,
 \qquad n=2\ell
 \quad\Longrightarrow\quad
 \operatorname{gap}H_{\mathrm{AKLT}}
 \geq\frac{g_*(\Delta,\ell)}{2\Delta}>0.
 \label{q:log-decoration}
\end{equation}
Thus $n<\log_3(144\Delta)+2$ is a sufficient even decoration count.

\label{q:thm-powers}
For $0\leq r\leq1$, let
$Q_r=(\partial_\lambda\rho^r)\rho^{-r}=H_r+A_r$ be its Hermitian and
anti-Hermitian decomposition.  With $\operatorname{ad}_K(O)=[K,O]$,
\begin{align}
 H_r&=\psi_r(\operatorname{ad}_K)H,
 &\psi_r(x)&=\frac{\sinh(rx)}{\sinh x},\quad\psi_r(0)=r,
 \label{q:power-H}\\
 A_r&=\chi_r(\operatorname{ad}_K)A,
 &\chi_r(x)&=\left(\frac{\sinh(rx/2)}{\sinh(x/2)}\right)^2,
 \quad\chi_r(0)=r^2.
 \label{q:power-A}
\end{align}
Both maps are completely positive, with completely bounded
operator norms $r$ and $r^2$, respectively.  Consequently
\[
 \|H_r\|\leq r\|H\|,\qquad
 \|A_r\|\leq r^2\|A\|.
\]
The estimates hold with an arbitrary ancillary system.  Moreover,
\begin{equation}
 \lim_{r\downarrow0}\frac{Q_r}{r}
 =\dot K=f(\operatorname{ad}_K)H,
 \qquad f(x)=\frac{x}{\sinh x},\quad f(0)=1.
 \label{q:log-response}
\end{equation}

\label{att:coarse-entropy}
Let $P_N\ll\sigma^{\otimes N}$ have finite relative entropy, and let
$f_{i,x_{-i}}$ be its full one-coordinate conditional density relative
to $\sigma$. Denote the law of its cell labels by $P_N^{(j)}$ and the
reference cell probabilities by $\sigma_j$. Then
\begin{align}
 0&\le D(P_N\Vert\sigma^{\otimes N})-
               D(P_N^{(j)}\Vert\sigma_j^{\otimes N})\\
 &\le\sum_{i=1}^N\mathbb E_{P_{N,-i}}
    \left[\operatorname{Ent}_\sigma(f_{i,x_{-i}})
              -\operatorname{Ent}_\sigma(\mathbb E_j f_{i,x_{-i}})\right].
 \label{att:coarse-bound}
\end{align}
Here $\operatorname{Ent}_\sigma(f)=\int f\log f\,d\sigma$ for a
probability density $f$.

\label{att:quadratic-pressure}
Let $\nu=g\sigma$ be a probability measure with $g\in L^p(\sigma)$
for some $p>1$. There are $t_0>0$ and $C_\nu<\infty$, independent
of $k$, such that
\begin{equation}
 t\,\mathbb E_{\nu^{\otimes N}}E_k
 \le \frac1N\log\int e^{tN E_k}\,d\nu^{\otimes N}
 \le t\,\mathbb E_{\nu^{\otimes N}}E_k+C_\nu t^2,
 \qquad |t|\le t_0.
 \label{att:quadratic-bound}
\end{equation}
The constants can be chosen uniformly when the exponent $p>1$ and the $L^p$ bound of $g$ are fixed. The assertion includes finiteness of the integrals and mean energies.

\label{att:good-rate}
For $0\le\gamma<\alpha$, $F_\gamma$ is lower semicontinuous and
has compact sublevels. For every $\gamma<a<\alpha$,
\begin{equation}
 F_\gamma(\mu)\ge(1-\gamma/a)H(\mu)
                          -(\gamma/a)\log C_a,
 \label{att:coercivity}
\end{equation}
where $C_a$ bounds $\int e^{-au}\,d\sigma$ over all normalized psh
potentials. If $\mu_j\to\mu$ weakly and
$H(\mu_j)\to H(\mu)<\infty$, then $E(\mu_j)\to E(\mu)$.

\label{att:full-laplace}
For every fixed $0\le\gamma<1/3$ and every
$\Phi\in C(\mathcal P(\mathbb P^2))$,
\begin{equation}
 \lim_{k\to\infty}\frac1N\log\int
       e^{N[\gamma E_k-\Phi(L_N)]}\,d\sigma^N
 =-\inf_{\mu\in\mathcal P(X)}[F_\gamma(\mu)+\Phi(\mu)].
 \label{att:full-laplace-eq}
\end{equation}
The empirical laws of the normalized attractive ensemble satisfy a
full speed-$N$ LDP with good rate
$F_\gamma-\inf F_\gamma$.

\label{att:design-laplace}
Fix any design order $t\ge1$ and $0<a<1/2$. Let
\[
 \begin{aligned}
 \mathcal D_t&=\{\mu:M_t(\mu)=I/\tbinom{t+2}{2}\},\\
 \Omega_N&=\{\|M_t(L_N)-I/\tbinom{t+2}{2}\|_{\rm HS}<N^{-a}\},
 \qquad Q_N=\sigma^N(\cdot\mid\Omega_N).
 \end{aligned}
\]
For every fixed $0\le\gamma<1/3$ and every continuous empirical tilt,
\begin{equation}
 \lim_{k\to\infty}\frac1N\log\int
 e^{N[\gamma E_k-\Phi(L_N)]}\,dQ_N
 =-\inf_{\mu\in\mathcal D_t}[H(\mu)-\gamma E(\mu)+\Phi(\mu)].
 \label{att:design-laplace-eq}
\end{equation}
The normalized empirical laws satisfy the full LDP with good rate
$F_\gamma+\iota_{\mathcal D_t}-\inf_{\mathcal D_t}F_\gamma$.

\label{tor:vertices}
Every monomial in $\det(z_i^\alpha)_{i,\alpha\in\mathcal A_m}$
is an exposed vertex of its Newton polytope. Consequently, if
\[
 A_m(\boldsymbol p)=
 \max_{\pi:\{1,\ldots,N\}\simeq\mathcal A_m}
 \prod_{i=1}^N N\binom m{\pi(i)}p_i^{\pi(i)},
\]
then
\begin{equation}
 \log A_m(\boldsymbol p)
 \le \int\log\|\Delta_k(\boldsymbol z)\|^2\,d\boldsymbol\theta
 \le \log A_m(\boldsymbol p)+\log N!.
 \label{tor:phase-squeeze}
\end{equation}
The logarithm is integrable for every such $\boldsymbol p$.

\label{tor:finite-certificate}
For every $\boldsymbol p\in(\Delta_q^\circ)^N$,
\begin{equation}
 D C_m(\boldsymbol p)-\frac{\log N}{k}
                       -\frac{\log N!}{kN}
 \le\int E_k(\boldsymbol z)\,d\boldsymbol\theta
 \le D C_m(\boldsymbol p).
 \label{tor:finite-certificate-bound}
\end{equation}
In particular the error is at most $2\log N/k$.

\label{tor:cost-limit}
Let $\eta$ be a probability on $\Delta_q^\circ$ such that
\begin{equation}
 \int b(p)\,d\eta(p)<\infty,
 \qquad b(p)=\sum_{j=0}^q-\log p_j.
 \label{tor:log-moment}
\end{equation}
For iid $p_1,p_2,\ldots$ with law $\eta$,
\[
 C_m(p_1,\ldots,p_N)\longrightarrow
 C(\eta):=\inf_{\kappa\in\Pi(\lambda,\eta)}
                   \int c(a,p)\,d\kappa(a,p)
\]
almost surely and in $L^1$ as $m\to\infty$ (along $m=Dk$ or all
integer degrees).

\label{tor:energy-transport}
Let $\mu$ be invariant under the standard projective torus, and let
$\eta$ be its squared-modulus pushforward. Under
\eqref{tor:log-moment}, its anticanonical pluricomplex energy is
\begin{equation}
 E(\mu)=D C(\eta).
 \label{tor:energy-transport-formula}
\end{equation}

\label{ac:canonical-poincare}
Let $(M,G)$ be a connected compact K\"ahler manifold and let
$e^{-\Phi}$ be a smooth metric on $-K_M$ satisfying
$i\partial\bar\partial\Phi\ge aG$, where $a>0$.
Let $\mu_\Phi$ be its canonical volume, normalized to mass one.
Then every smooth complex-valued function $F$ satisfies
\begin{equation}
 \int_M|F-\mu_\Phi(F)|^2\,d\mu_\Phi
 \le \frac1a\int_M|\bar\partial F|_G^2\,d\mu_\Phi.
 \label{ac:canonical-poincare-eq}
\end{equation}

\label{ac:variance}
Suppose $0\le\gamma<1$ and $Z_{k,\gamma}<\infty$.
Then, for every smooth function $F$ on $X^N$,
\begin{equation}
 \operatorname{Var}_{P_{k,\gamma}}(F)
 \le\frac1{1-\gamma}
       \int|\bar\partial F|_{G_M}^2\,dP_{k,\gamma}.
 \label{ac:variance-eq}
\end{equation}
For a real $f\in C^\infty(X)$, put
\[
 A_f=\sup_X|\bar\partial f|_{G_X}^2,
 \qquad
 -C_fG_X\le i\partial\bar\partial f\le C_fG_X.
\]
Here $C_f$ is any nonnegative constant satisfying the displayed
inequalities.  If
$dP_{k,\gamma,t,f}\propto e^{t\sum_i f(x_i)}dP_{k,\gamma}$ and
$|t|C_f<1-\gamma$, then
\begin{equation}
 \operatorname{Var}_{P_{k,\gamma,t,f}}
          \left(\sum_{i=1}^N f(x_i)\right)
 \le\frac{NA_f}{1-\gamma-|t|C_f}.
 \label{ac:tilted-variance}
\end{equation}
Every one-particle marginal of $P_{k,\gamma}$ is exactly $\sigma$.

\label{ac:ward}
Suppose $\gamma<1$ and $Z_{k,\gamma}<\infty$, using the same
density formula also for negative $\gamma$.
For traceless Hermitian $D\times D$ matrices $H,K$, let
$f_H(z)=\operatorname{tr}(HP_z)$ and $S_H=\sum_i f_H(z_i)$.
Then
\begin{equation}
 \operatorname{Cov}_{P_{k,\gamma}}(S_H,S_K)
 =\frac{N\operatorname{tr}(HK)}{D(D+1)(1-\gamma)}.
 \label{ac:ward-covariance}
\end{equation}
In the attractive range $0\le\gamma<1$, the constant
$1/(1-\gamma)$ in \eqref{ac:variance-eq} is therefore optimal.
For two distinct labels,
\begin{equation}
 \mathbb E_{P_{k,\gamma}}\operatorname{tr}(P_{z_1}P_{z_2})
 =\frac1D+
   \frac{(D-1)\gamma}{D(N-1)(1-\gamma)}.
 \label{ac:pair-overlap}
\end{equation}
Equivalently, with $M_1=N^{-1}\sum_iP_{z_i}$,
\begin{equation}
 \mathbb E_{P_{k,\gamma}}
      \left\|M_1-\frac{I}{D}\right\|_{\rm HS}^2
       =\frac{D-1}{DN(1-\gamma)}.
 \label{ac:first-moment-variance}
\end{equation}
Consequently finiteness of the partition function in this range
requires $\gamma<1-1/N$.

\label{ac:concentration}
Suppose $0\le\gamma<1$, and suppose $Z_{k,\gamma}<\infty$ for the
values of $k$ under consideration.  For $f\in C^\infty(X,\mathbb R)$
and $|t|C_f<1-\gamma$,
\begin{equation}
 \log\mathbb E_{P_{k,\gamma}}
       \exp\!\left(t\sum_{i=1}^N[f(x_i)-\sigma(f)]\right)
 \le\frac{NA_ft^2}{2(1-\gamma-|t|C_f)}.
 \label{ac:mgf}
\end{equation}
In particular, if $A_f>0$, then for every $s>0$,
\begin{equation}
 P_{k,\gamma}\!\left(
    \left|\frac1N\sum_i f(x_i)-\sigma(f)\right|\ge s\right)
 \le 2\exp\!\left(
    -\frac{N(1-\gamma)s^2}{2(A_f+C_fs)}\right).
 \label{ac:tail}
\end{equation}
If $A_f=0$, then $f$ is constant and the deviation probability is
zero.  These conclusions are unconditional for $0\le\gamma<1/D$.

\label{cy:finite-convexity}
For every sufficiently large fixed $k$, the functional
$\overline E_k$ is convex on smooth strictly positive probability
volumes. If $\eta$ is a smooth signed measure of total mass zero and
$\mu_t=\mu+t\eta$ remains strictly positive, then
\begin{equation}
 \frac{d}{dt}\overline E_k(\mu_t)\bigg|_{t=0}
 =-\int_X U_{k,\mu}(x)\,d\eta(x),\qquad
 U_{k,\mu}(x)=\frac1k\int_{X^{N-1}}
        \log\|\Delta_k(x,\mathbf y)\|^2\,d\mu^{N-1}(\mathbf y).
 \label{cy:first-variation}
\end{equation}

\label{cy:green-formula}
Let $\mu$ be any smooth strictly positive probability volume on $X$.
There is a unique smooth potential $\phi_\mu$, normalized by
$\int_X\phi_\mu\,d\mu=0$, such that
\[
 \frac{(\omega+dd^c\phi_\mu)^q}{V}=\mu,
 \qquad \omega+dd^c\phi_\mu>0.
\]
The mean-zero determinant potentials
\begin{equation}
 \phi_{k,\mu}(x)=\frac1k\int_{X^{N_k-1}}
       \log\|\Delta_k(x,\mathbf y)\|^2\,d\mu^{N_k-1}(\mathbf y)
      -C_{k,\mu},
 \quad
 C_{k,\mu}=\frac1k\int_{X^{N_k}}\log\|\Delta_k\|^2\,d\mu^{N_k}
 \label{cy:potential-formula}
\end{equation}
converge to $\phi_\mu$ in $L^p(X,\sigma)$, equivalently in
$L^p(X,\mu)$, for every fixed $1\le p<\infty$. The formula is independent of the chosen basis after
the displayed centering.

\label{cy:interpolation-sampling}
Draw $\mathbf Y=(Y_2,\ldots,Y_N)$ independently from $\mu$.
Almost surely the section
$s_{\mathbf Y}(x)=\Delta_k(x,\mathbf Y)$ is nonzero and is the unique
section vanishing at these $N-1$ points, up to scale. Define its
mean-zero potential
\[
 u_{k,\mathbf Y}(x)=\frac1k\log\|s_{\mathbf Y}(x)\|^2
                 -\int_X\frac1k\log\|s_{\mathbf Y}\|^2\,d\mu.
\]
Then
\begin{equation}
 \mathbb E\frac1k[Z_{s_{\mathbf Y}}]
       =\omega+dd^c\phi_{k,\mu}
       \longrightarrow\omega+dd^c\phi_\mu
 \label{cy:divisor-limit}
\end{equation}
weakly as currents. Moreover, if $u^{(1)},\ldots,u^{(M)}$ are independent
copies of $u_{k,\mathbf Y}$, then, for every $a>0$ with
\[
 C_a(\mu):=\sup_{\substack{v\in\operatorname{PSH}(X,\omega)\\\sup v=0}}
                      \int e^{-av}\,d\mu<\infty,
\]
one has the uniform sampling estimate
\begin{equation}
 \mathbb E\left\|\frac1M\sum_{j=1}^M u^{(j)}-\phi_{k,\mu}
             \right\|_{L^2(\mu)}^2
       \le\frac{2C_a(\mu)}{a^2M}.
 \label{cy:sampling-bound}
\end{equation}
On the anticanonical projective plane, if $\mu=g\sigma$, one may take
$a=1/6$, obtaining the explicit bound $192\|g\|_\infty/M$.

Exact centering integrals can also be replaced by sampling. For each
section independently draw $J\ge1$ calibration points from $\mu$
and subtract their mean log squared norm in place of its $\mu$ integral.
Then the left side of \eqref{cy:sampling-bound} is bounded by
\begin{equation}
 \frac{2C_a(\mu)}{a^2M}\left(1+\frac1J\right).
 \label{cy:sample-centered-bound}
\end{equation}
